const p1 = fetch('/users/1');
const p2 = fetch('/posts/1');

// AVOID: Sequential (Slow! Takes p1 time + p2 time)
// const u = await p1; 
// const p = await p2;

// GOOD: Parallel (Fast! Takes max of p1 or p2 time)
try {
  const [userRes, postRes] = await Promise.all([p1, p2]);
  console.log("Both fetched successfully!");
} catch (error) {
  // If p1 OR p2 fails, it lands here instantly
  console.error("One of them failed!", error);
}

